import ast,math,random
from pathlib import Path
# Execute only the extracted sign helper using a minimal list-backed tensor;
# this is an implementation diagnostic, not a native tensor/autograd test.
model=next(n for n in ast.parse(Path('candidate.py').read_text()).body if isinstance(n,ast.ClassDef))
helper=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='_reflect_second_view')
helper.decorator_list=[]
class Tensor:
 def __init__(self,rows): self.rows=[list(row) for row in rows]; self.shape=(len(rows),len(rows[0]) if rows else 0)
 def __getitem__(self,index): return Tensor(self.rows[index])
 def __mul__(self,scale): return Tensor([[x*scale for x in row] for row in self.rows])
class Stub:
 @staticmethod
 def cat(values,dim=0):
  assert dim==0
  return Tensor([row for value in values for row in value.rows])
namespace={'torch':Stub}
exec(compile(ast.fix_missing_locations(ast.Module(body=[helper],type_ignores=[])),'extracted_sign_helper','exec'),namespace)
reflect=namespace['_reflect_second_view']
rng=random.Random(6601); cases=0
for half in [1,2,3,7,17]:
 for width in [1,3,16,112]:
  rows=[[rng.uniform(-10,10) for _ in range(width)] for _ in range(2*half)]
  rows[0][0]=0.0
  for flag in [False,True]:
   value=Tensor(rows); out=reflect(value,flag)
   expected=rows[:half]+[[x*(-1 if flag else 1) for x in row] for row in rows[half:]]
   assert out.rows==expected and value.rows==rows
   assert reflect(out,flag).rows==rows
   cases+=1
try: reflect(Tensor([[1],[2],[3]]),True)
except ValueError: pass
else: raise AssertionError('Odd paired batch accepted')
# Independent centered-coordinate algebra, including norm-matched coarse basis.
patterns=[[0]*100,[1]*100]+[[int(i>=100-n) for i in range(100)] for n in [1,2,9,10,11,17,64,99]]
patterns += [[int(rng.random()<rng.random()) for _ in range(100)] for _ in range(200)]
def coefficients(valid,reflected=False):
 positions=[(1-i/9 if reflected else i/9) for i in range(10)]
 ranks=[(1-j/9 if reflected else j/9) for j in range(10)]
 counts=[sum(valid[j*10:j*10+10]) for j in range(10)]
 local=[]
 for j,count in enumerate(counts):
  mean=sum(positions[i]*valid[j*10+i] for i in range(10))/max(count,1)
  local += [valid[j*10+i]*(positions[i]-mean) for i in range(10)]
 total=max(sum(valid),1)
 mean=sum(ranks[j]*counts[j] for j in range(10))/total
 coarse=[valid[j*10+i]*(ranks[j]-mean) for j in range(10) for i in range(10)]
 ln=sum(x*x for x in local); cn=sum(x*x for x in coarse)
 scale=math.sqrt(ln/max(cn,1e-12))*(cn>1e-12)
 return local,[x*scale for x in coarse]
for valid in patterns:
 a,b=coefficients(valid); ar,br=coefficients(valid,True)
 for orig,rev in [(a,ar),(b,br)]:
  assert all(math.isfinite(x) for x in orig+rev)
  assert all(abs(x+y)<1e-11 for x,y in zip(orig,rev))
  assert abs(sum(x*x for x in orig)-sum(x*x for x in rev))<1e-10
  assert all(x==0 for x,v in zip(orig,valid) if not v)
  assert abs(sum(orig))<1e-10
 values=[rng.uniform(-3,3) for _ in valid]
 for orig,rev in [(a,ar),(b,br)]:
  assert abs(sum(x*v for x,v in zip(orig,values))+sum(x*v for x,v in zip(rev,values)))<1e-10
# Analytic view-averaging symmetry and relative-sign caveat, independent of network.
def f(l,c): return math.tanh(0.4*l-0.7*c+0.2*l*c+0.1)
def average(l,c,rl,rc): return (f(l,c)+f((-l if rl else l),(-c if rc else c)))*0.5
for _ in range(200):
 l,c=rng.uniform(-3,3),rng.uniform(-3,3)
 assert abs(average(l,c,True,False)-average(-l,c,True,False))<1e-15
 assert abs(average(l,c,False,True)-average(l,-c,False,True))<1e-15
 assert abs(average(l,c,True,True)-average(-l,-c,True,True))<1e-15
assert abs(average(1,2,True,True)-average(-1,2,True,True))>0.01
print(f'PASS extracted helper {cases} shape/sign/identity/involution/immutability cases and odd-batch rejection; {len(patterns)} centered-coordinate/norm/support/contraction patterns; 200 analytic probability-symmetry cases with explicit joint-relative-sign counterexample. No PyTorch, gradients, BF16 or model predictions executed.')
